from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and separate groups of parentheses
    groups = []
    current_group = ""
    open_braces = 0

    for char in paren_string:
        if char == "(":
            open_braces += 1
        elif char == ")":
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced
    balanced_groups = []
    for group in groups:
        if group.count("(") == group.count(")"):
            balanced_groups.append(group)

    # Step 4: Ignore nested groups within each other
    final_groups = []
    for group in balanced_groups:
        if all("(" not in nested_group for nested_group in final_groups):
            final_groups.append(group)

    # Step 5: Return the list of separated groups
    return final_groups

